('APX-S-2825-1', 'APX-C-2825', 1, null, null, null, 'Mei Tactical suit.png = Mei: East Asian woman, long straight black hair, black leather tactical suit with gold accent piping along collar, shoulders, and wrist cuffs, gold buckle utility belt, dual thigh holsters, black flat-heeled boots with gold chevron trim. Dex Rei Tactical suit.png = Dex Rei: East Asian woman, dark green twin ponytails with blunt-cut bangs, dark green leather tactical suit with black reinforced shoulder pads and knee panels, black utility belt with hip pouch, single thigh holster, black lace-up heeled combat boots, black tactical gloves.', null, null, 'Mei Tactical suit.png = Mei: East Asian woman, long straight black hair, black leather tactical suit with gold accent piping along collar, shoulders, and wrist cuffs, gold buckle utility belt, dual thigh holsters, black flat-heeled boots…', null, null, null, null, null, null),
('APX-S-2825-2', 'APX-C-2825', 2, null, null, null, 'Hallway 2.PNG = Hallway environment reference. Style & Mood: Aggressive espionage-thriller intensity dialed higher. Fluorescent tubes flicker under impact vibrations, casting staccato light across polished epoxy floors. Desaturated teal-gray palette, motion blur on extremities during fast rotation, sharp focus snapping to point of contact on every strike. Sweat droplets flung from hair on spinning moves catch the overhead light. Dynamic Description: Handheld medium shot already in motion — Mei drives forward with a rapid three-punch combination, fists cutting the air.', null, null, 'Hallway 2.PNG = Hallway environment reference. Style & Mood: Aggressive espionage-thriller intensity dialed higher. Fluorescent tubes flicker under impact vibrations, casting staccato light across polished epoxy floors.', null, 'driving', null, null, null, null),
('APX-S-2825-3', 'APX-C-2825', 3, null, null, null, null, 1150, 599, 'Dex Rei weaves back, parries the third strike wide, and fires a roundhouse kick that whips her green ponytails in a wide arc, boot connecting flush with Mei''s raised guard.', null, 'sliding; driving', null, null, null, null),
('APX-S-2825-4', 'APX-C-2825', 4, null, null, null, null, 1750, 490, 'She redirects Mei''s momentum, pivots, and launches a spinning jump kick — her entire body rotating airborne, green suit blurring, boot arcing toward Mei''s head.', null, 'leaping', null, null, 'temple', null),
('APX-S-2825-5', 'APX-C-2825', 5, null, null, null, null, 2241, 545, 'The kick grazes Dex Rei''s shoulder as she ducks. Mei vaults over it, lands, and Dex Rei is already rising with a vertical spinning crescent kick that forces Mei to arch backward, the boot passing centimeters from her chin.', null, 'vaulting', null, null, null, null),
('APX-S-2825-6', 'APX-C-2825', 6, null, null, null, 'A flicker of mutual acknowledgment passes between them — Dex Rei''s smirk, Mei''s narrowed eyes — before they surge forward again. Static Descriptio', null, null, 'A flicker of mutual acknowledgment passes between them — Dex Rei''s smirk, Mei''s narrowed eyes — before they surge forward again.', null, null, null, null, null, null),
('APX-S-2812-1', 'APX-C-2812', 1, 0, 3, 3, null, 912, 163, '[ Shot] Wrestler 1 sprints toward the ring ropes, bounces off the tensioned cables with physics, and accelerates back toward the center.', null, 'sprinting', null, null, null, null),
